async fn workout_set_list(
    OntogenState(ontogen_state): OntogenState<::std::sync::Arc<AppState>>,
    _: OntogenAcceptGuard,
    query: OntogenQuery<OntogenListParams>,
) -> Result<OntogenResponse, OntogenErrorObject> {
    let order = query.sort_order("workout-sets")?;
    let include = query.include_paths("workout-sets", &["workout", "exercise"], &[])?;
    let link_query = query.link_query(include.as_deref())?;
    let ontogen_store = ontogen_state.store().await.map_err(ontogen_internal_error)?;
    let items = workout_set::list(&ontogen_store, &order).await.map_err(ontogen_app_error)?;
    let collection = "/api/workout-sets";
    let data: Vec<_> = items.iter().map(|entity| ontogen_workout_set_as_resource(entity, collection)).collect();
    let mut document = OntogenDocument::new(data, OntogenLinks::new(link_query.href(collection)));
    if let Some(paths) = &include {
        document = document.with_included(ontogen_workout_set_included(&ontogen_state, &items, paths).await?);
    }
    Ok(::ontogen_jsonapi::response::ok(&document))
}

